import { useCallback, useEffect, useRef, useState } from "react";
import { Checkbox, Tooltip } from "@fluentui/react-components";
import {
  CheckmarkCircle24Regular,
  ErrorCircle24Regular,
  Warning24Regular,
} from "@fluentui/react-icons";
import { ja } from "../strings/ja";
import { HsButton } from "../components/primitives/Button";
import { HsDialog } from "../components/primitives/Dialog";
import { HsProgress } from "../components/primitives/Progress";
import type { ToolPathOverrides } from "../diagnostics/types";
import type { ExportPort } from "./port";
import {
  exportErrorCode,
  pdfBlocked,
  EXPORT_FORMAT_GROUPS,
  type ExportCapabilities,
  type ExportFormatId,
  type ExportResult,
} from "./types";

type Phase = "loading" | "form" | "running" | "done" | "error";
type ErrorKind = "permission" | "unavailable" | "musescore" | "failed";

const ERROR_TITLE: Record<ErrorKind, string> = {
  permission: ja.errors.exportPermissionDenied.title,
  unavailable: ja.errors.engineUnavailable.title,
  musescore: ja.errors.musescoreMissing.title,
  failed: ja.errors.exportFailed.title,
};

const ERROR_BODY: Record<ErrorKind, string> = {
  permission: ja.errors.exportPermissionDenied.body,
  unavailable: ja.errors.engineUnavailable.body,
  musescore: ja.errors.musescoreMissing.body,
  failed: ja.errors.exportFailed.body,
};

/**
 * 書き出し dialog (GUI_UX_SPEC §17, §20; issue UI-060).
 *
 * Formats (all checked by default):
 *   楽譜: コンサートピッチ / F管ホルン MusicXML
 *   PDF:  コンサートピッチ / F管ホルン PDF  — disabled when MuseScore is
 *         missing, with the spec'd note + 場所を指定 recovery; MusicXML and
 *         MIDI stay available (acceptance: "missing MuseScore does not
 *         block other formats").
 *   MIDI: 再生用MIDI（実音） — sounding pitch only (ENG-001).
 *
 * Phases: loading → form → running → done | error. Errors keep the §20
 * shape (何が失敗したか → 影響 → 次にできること) and never render engine
 * output — only stable ExportError codes map to Japanese recovery copy.
 */
export function ExportDialog({
  open,
  onOpenChange,
  port,
  defaultDestination,
  toolOverrides,
  onOpenSettings,
  onOpenDiagnostics,
  onAnnounce,
}: {
  open: boolean;
  onOpenChange(open: boolean): void;
  port: ExportPort;
  /** 設定 → 書き出し → 既定の保存先 ("" = ask the port). */
  defaultDestination: string;
  /** 設定 → ツール user paths — non-empty paths override probing. */
  toolOverrides?: ToolPathOverrides;
  /** Recovery: opens 設定 focused on the 書き出し category. */
  onOpenSettings(category: "export"): void;
  onOpenDiagnostics(): void;
  onAnnounce(message: string): void;
}) {
  const [phase, setPhase] = useState<Phase>("loading");
  const [caps, setCaps] = useState<ExportCapabilities | null>(null);
  const [destination, setDestination] = useState("");
  const [selected, setSelected] = useState<Record<ExportFormatId, boolean>>({
    concertMusicxml: true,
    hornMusicxml: true,
    concertPdf: true,
    hornPdf: true,
    playbackMidi: true,
    sourceAudio: true,
  });
  const [result, setResult] = useState<ExportResult | null>(null);
  const [errorKind, setErrorKind] = useState<ErrorKind>("failed");
  // Stale-response guard: a probe/export finishing after close or a newer
  // attempt must not overwrite the current phase.
  const generation = useRef(0);

  const e = ja.exportSheet;
  const errs = ja.errors;

  // Probe capabilities + destination when the dialog opens.
  useEffect(() => {
    if (!open) return;
    const gen = ++generation.current;
    setPhase("loading");
    setCaps(null);
    setResult(null);
    setSelected({
      concertMusicxml: true,
      hornMusicxml: true,
      concertPdf: true,
      hornPdf: true,
      playbackMidi: true,
      sourceAudio: true,
    });
    let cancelled = false;
    void (async () => {
      try {
        const [capabilities, fallbackDir] = await Promise.all([
          port.capabilities(toolOverrides),
          defaultDestination
            ? Promise.resolve(defaultDestination)
            : port.defaultDestination(),
        ]);
        if (cancelled || generation.current !== gen) return;
        setCaps(capabilities);
        setDestination(defaultDestination || fallbackDir);
        setPhase("form");
      } catch (err) {
        if (cancelled || generation.current !== gen) return;
        setErrorKind(
          exportErrorCode(err) === "ENGINE_UNAVAILABLE"
            ? "unavailable"
            : "failed",
        );
        setPhase("error");
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [open, port, defaultDestination, toolOverrides]);

  const close = useCallback(() => {
    generation.current += 1;
    onOpenChange(false);
  }, [onOpenChange]);

  const blocked = caps ? pdfBlocked(caps) : false;
  // #87: the audio bundle needs a real path — browser-held bytes and
  // pathless recordings keep the checkbox off with an honest tooltip.
  const audioBlocked = caps != null && !caps.audioAvailable;
  const running = phase === "running";
  // Formats that will actually export — checked AND not blocked.
  // anyChecked alone let submit run with an empty list when every
  // checked format was blocked (e.g. PDF-only selection + no MuseScore).
  const effectiveFormats = (
    Object.keys(selected) as ExportFormatId[]
  ).filter(
    (f) =>
      selected[f] &&
      !(blocked && EXPORT_FORMAT_GROUPS[f] === "pdf") &&
      !(audioBlocked && f === "sourceAudio"),
  );

  const submit = useCallback(async () => {
    const gen = ++generation.current;
    setPhase("running");
    try {
      const res = await port.export({
        formats: effectiveFormats,
        destination,
      });
      if (generation.current !== gen) return;
      setResult(res);
      setPhase("done");
      onAnnounce(ja.notifications.exportDone);
    } catch (err) {
      if (generation.current !== gen) return;
      const code = exportErrorCode(err);
      setErrorKind(
        code === "PERMISSION_DENIED"
          ? "permission"
          : code === "ENGINE_UNAVAILABLE"
            ? "unavailable"
            : code === "MUSESCORE_UNAVAILABLE"
              ? "musescore"
              : "failed",
      );
      setPhase("error");
    }
  }, [effectiveFormats, port, destination, onAnnounce]);

  const pickDestination = useCallback(async () => {
    try {
      const dir = await port.chooseDestination(destination);
      if (dir) setDestination(dir);
    } catch {
      /* unsupported picker — the path row stays editable nowhere else,
         so surface the honest failure instead of dying silently */
      onAnnounce(ja.exportSheet.destinationPickFailed);
    }
  }, [port, destination, onAnnounce]);

  const reveal = useCallback(async () => {
    const dir = result?.destination ?? destination;
    const ok = await port.revealInExplorer(dir).catch(() => false);
    if (!ok) onAnnounce(ja.exportSheet.revealFailed);
  }, [port, result, destination, onAnnounce]);

  const goToMuseScoreSettings = useCallback(() => {
    close();
    onOpenSettings("export");
  }, [close, onOpenSettings]);

  const toggle =
    (key: ExportFormatId) =>
    (_: unknown, d: { checked: boolean | "mixed" }) =>
      setSelected((s) => ({ ...s, [key]: d.checked === true }));

  const title =
    phase === "done"
      ? e.completeTitle
      : phase === "error"
        ? ERROR_TITLE[errorKind]
        : e.title;

  const formatRow = (id: ExportFormatId) => {
    const pdfOff = blocked && EXPORT_FORMAT_GROUPS[id] === "pdf";
    const audioOff = audioBlocked && id === "sourceAudio";
    const disabled = running || pdfOff || audioOff;
    const checkbox = (
      <Checkbox
        checked={selected[id]}
        onChange={toggle(id)}
        label={e.options[id]}
        disabled={disabled}
      />
    );
    // Disabled checkboxes can't announce *why* — the spec'd tooltip does.
    if (audioOff) {
      return (
        <Tooltip
          key={id}
          content={e.audioDisabledTooltip}
          relationship="label"
        >
          <span className="hs-export__option">{checkbox}</span>
        </Tooltip>
      );
    }
    return pdfOff ? (
      <Tooltip
        key={id}
        content={e.pdfDisabledTooltip}
        relationship="label"
      >
        <span className="hs-export__option">{checkbox}</span>
      </Tooltip>
    ) : (
      <span key={id} className="hs-export__option">
        {checkbox}
      </span>
    );
  };

  return (
    <HsDialog
      open={open}
      onOpenChange={(o) => (o ? onOpenChange(true) : close())}
      title={title}
      actions={
        phase === "form" || running ? (
          <>
            <HsButton onClick={close}>{ja.common.cancel}</HsButton>
            <HsButton
              variant="primary"
              disabled={effectiveFormats.length === 0 || running || !destination}
              loading={running}
              onClick={() => void submit()}
            >
              {running ? e.running : e.submit}
            </HsButton>
          </>
        ) : phase === "done" ? (
          <>
            <HsButton onClick={() => void reveal()}>
              {e.revealInExplorer}
            </HsButton>
            <HsButton variant="primary" onClick={close}>
              {ja.common.close}
            </HsButton>
          </>
        ) : phase === "error" ? (
          <>
            {errorKind === "permission" || errorKind === "failed" ? (
              <HsButton onClick={() => setPhase("form")}>
                {errs.exportPermissionDenied.actions.chooseDestination}
              </HsButton>
            ) : null}
            {errorKind === "failed" ? (
              <HsButton onClick={() => void submit()}>
                {errs.exportFailed.actions.retry}
              </HsButton>
            ) : null}
            {errorKind === "musescore" ? (
              <HsButton
                variant="primary"
                onClick={goToMuseScoreSettings}
              >
                {errs.musescoreMissing.actions.specifyMusescore}
              </HsButton>
            ) : null}
            {errorKind === "unavailable" ? (
              <HsButton
                variant="primary"
                onClick={() => {
                  close();
                  onOpenDiagnostics();
                }}
              >
                {errs.engineUnavailable.actions.diagnostics}
              </HsButton>
            ) : null}
            <HsButton onClick={close}>{ja.common.close}</HsButton>
          </>
        ) : undefined
      }
    >
      {phase === "loading" ? (
        <HsProgress label={e.loading} />
      ) : phase === "form" || running ? (
        <div className="hs-export">
          <h3 className="hs-export__section">{e.scoreSection}</h3>
          <div className="hs-export__group">
            {formatRow("concertMusicxml")}
            {formatRow("hornMusicxml")}
          </div>

          <h3 className="hs-export__section">{e.pdfSection}</h3>
          <div className="hs-export__group">
            {formatRow("concertPdf")}
            {formatRow("hornPdf")}
          </div>
          {blocked ? (
            <p className="hs-export__note" role="note">
              <Warning24Regular aria-hidden="true" />
              <span>{e.museScoreMissingNote}</span>
              <HsButton
                variant="subtle"
                size="small"
                onClick={goToMuseScoreSettings}
              >
                {e.specifyMuseScore}
              </HsButton>
            </p>
          ) : null}

          <h3 className="hs-export__section">{e.midiSection}</h3>
          <div className="hs-export__group">{formatRow("playbackMidi")}</div>

          <h3 className="hs-export__section">{e.audioSection}</h3>
          <div className="hs-export__group">{formatRow("sourceAudio")}</div>

          <div className="hs-export__dest">
            <span className="hs-export__dest-label">{e.destination}</span>
            <span className="hs-export__dest-path" title={destination}>
              {destination}
            </span>
            <HsButton
              variant="secondary"
              size="small"
              disabled={running}
              onClick={() => void pickDestination()}
            >
              {ja.common.browse}
            </HsButton>
          </div>

          {running ? (
            <HsProgress label={e.running} className="hs-export__progress" />
          ) : null}
        </div>
      ) : phase === "done" ? (
        <div className="hs-export">
          <p className="hs-export__done">
            <CheckmarkCircle24Regular
              aria-hidden="true"
              className="hs-export__done-icon"
            />
            <span>
              {e.completeCount.replace(
                "{count}",
                String(result?.files.length ?? 0),
              )}
            </span>
          </p>
          <ul className="hs-export__files">
            {result?.files.map((f) => (
              <li key={f.format} title={f.path}>
                {f.name}
              </li>
            ))}
          </ul>
        </div>
      ) : (
        <div className="hs-export">
          <p className="hs-export__error">
            <ErrorCircle24Regular
              aria-hidden="true"
              className="hs-export__error-icon"
            />
            <span>{ERROR_BODY[errorKind]}</span>
          </p>
        </div>
      )}
    </HsDialog>
  );
}

// @vitest-environment jsdom
import { describe, expect, it } from "vitest";
import { buildMidiFile, midiNotesFromMusicXml } from "./midi";

const SCALE_XML = `<?xml version="1.0" encoding="UTF-8"?>
<score-partwise version="4.0">
  <movement-title>Test</movement-title>
  <part-list><score-part id="P1"><part-name>Horn</part-name></score-part></part-list>
  <part id="P1">
    <measure number="1">
      <attributes><divisions>1</divisions><key><fifths>0</fifths></key>
        <time><beats>4</beats><beat-type>4</beat-type></time></attributes>
      <sound tempo="120"/>
      <note id="hs-sn-000001-1"><pitch><step>C</step><octave>4</octave></pitch><duration>1</duration><type>quarter</type></note>
      <note id="hs-sn-000002-1"><pitch><step>E</step><octave>4</octave></pitch><duration>1</duration><type>quarter</type></note>
      <note id="hs-sn-000003-1"><pitch><step>G</step><octave>4</octave></pitch><duration>2</duration><type>half</type></note>
    </measure>
  </part>
</score-partwise>`;

const TIED_XML = `<?xml version="1.0"?>
<score-partwise><part-list><score-part id="P1"><part-name>x</part-name></score-part></part-list>
  <part id="P1">
    <measure number="1"><attributes><divisions>2</divisions></attributes>
      <sound tempo="60"/>
      <note><pitch><step>D</step><octave>4</octave></pitch><duration>2</duration><tie type="start"/></note>
      <note><pitch><step>D</step><octave>4</octave></pitch><duration>2</duration><tie type="stop"/></note>
      <note><rest/><duration>1</duration></note>
      <note><pitch><step>F</step><alter>1</alter><octave>4</octave></pitch><duration>1</duration></note>
    </measure>
  </part>
</score-partwise>`;

describe("midiNotesFromMusicXml", () => {
  it("maps quarter/half durations to 480-tick onsets", () => {
    const { notes, tempoBpm, meter } = midiNotesFromMusicXml(SCALE_XML);
    expect(tempoBpm).toBe(120);
    expect(meter).toBe("4/4");
    expect(notes).toEqual([
      { on: 0, off: 480, midi: 60 },
      { on: 480, off: 960, midi: 64 },
      { on: 960, off: 1920, midi: 67 },
    ]);
  });

  it("merges tie start/stop pairs into one sustained note", () => {
    const { notes, tempoBpm } = midiNotesFromMusicXml(TIED_XML);
    expect(tempoBpm).toBe(60);
    // divisions=2: D4 spans 4 divisions = 960 ticks; F#4 follows a rest.
    expect(notes).toEqual([
      { on: 0, off: 960, midi: 62 },
      { on: 1200, off: 1440, midi: 66 },
    ]);
  });

  it("throws on malformed XML", () => {
    expect(() => midiNotesFromMusicXml("<score-partwise><part>")).toThrow();
  });
});

describe("buildMidiFile", () => {
  it("emits a valid SMF header and track chunk", () => {
    const bytes = buildMidiFile(SCALE_XML);
    // MThd, len 6, format 0, 1 track, 480 tpq
    expect(Array.from(bytes.slice(0, 4))).toEqual([0x4d, 0x54, 0x68, 0x64]);
    expect(Array.from(bytes.slice(4, 8))).toEqual([0, 0, 0, 6]);
    expect(Array.from(bytes.slice(8, 14))).toEqual([0, 0, 0, 1, 0x01, 0xe0]);
    expect(Array.from(bytes.slice(14, 18))).toEqual([0x4d, 0x54, 0x72, 0x6b]);
    const trackLen =
      (bytes[18] << 24) | (bytes[19] << 16) | (bytes[20] << 8) | bytes[21];
    expect(trackLen).toBe(bytes.length - 22);
    // End-of-track meta event is the last three bytes.
    expect(Array.from(bytes.slice(-3))).toEqual([0xff, 0x2f, 0x00]);
  });

  it("contains a tempo meta event for 120bpm (500000us/qn)", () => {
    const bytes = buildMidiFile(SCALE_XML);
    const body = Array.from(bytes);
    const idx = body.findIndex(
      (_, i) =>
        body[i] === 0xff && body[i + 1] === 0x51 && body[i + 2] === 0x03,
    );
    expect(idx).toBeGreaterThan(-1);
    const us = (body[idx + 3] << 16) | (body[idx + 4] << 8) | body[idx + 5];
    expect(us).toBe(500000);
  });

  it("emits program change + note on/off pairs", () => {
    const bytes = buildMidiFile(SCALE_XML);
    const body = Array.from(bytes);
    expect(body).toContain(0xc0);
    const noteOns = body.filter((b, i) => b === 0x90 && body[i + 2] === 80);
    const noteOffs = body.filter((b) => b === 0x80);
    expect(noteOns.length).toBe(3);
    expect(noteOffs.length).toBe(3);
  });
});

// #160: mid-piece tempo/meter changes + per-part ties.
const DRIFT_XML = [
  '<?xml version="1.0"?>',
  '<score-partwise><part-list><score-part id="P1"><part-name>x</part-name></score-part></part-list>',
  '<part id="P1">',
  '  <measure number="1"><attributes><divisions>1</divisions>',
  '    <time><beats>4</beats><beat-type>4</beat-type></time></attributes>',
  '    <direction><direction-type><metronome><beat-unit>quarter</beat-unit><per-minute>120</per-minute></metronome></direction-type><sound tempo="120"/></direction>',
  '    <note><pitch><step>C</step><octave>4</octave></pitch><duration>4</duration></note>',
  '  </measure>',
  '  <measure number="2"><attributes>',
  '    <time><beats>3</beats><beat-type>4</beat-type></time></attributes>',
  '    <direction><sound tempo="60"/></direction>',
  '    <note><pitch><step>E</step><octave>4</octave></pitch><duration>3</duration></note>',
  '  </measure>',
  '</part></score-partwise>',
].join("");

const TWOPART_TIE_XML = [
  '<?xml version="1.0"?>',
  '<score-partwise><part-list>',
  '  <score-part id="P1"><part-name>a</part-name></score-part>',
  '  <score-part id="P2"><part-name>b</part-name></score-part></part-list>',
  '<part id="P1"><measure number="1"><attributes><divisions>1</divisions></attributes>',
  '  <note><pitch><step>D</step><octave>4</octave></pitch><duration>1</duration><tie type="start"/></note>',
  '  <note><pitch><step>D</step><octave>4</octave></pitch><duration>1</duration><tie type="stop"/></note>',
  '</measure></part>',
  '<part id="P2"><measure number="1"><attributes><divisions>1</divisions></attributes>',
  '  <note><pitch><step>D</step><octave>4</octave></pitch><duration>2</duration></note>',
  '</measure></part>',
 '</score-partwise>',
].join("");

/** Decode SMF events as (absoluteTick, bytes) pairs for assertions. */
function smfEvents(bytes: Uint8Array): { tick: number; bytes: number[] }[] {
  const body = Array.from(bytes.slice(22));
  const out: { tick: number; bytes: number[] }[] = [];
  let i = 0;
  let tick = 0;
  while (i < body.length) {
    let delta = 0;
    let b = body[i++];
    while (b & 0x80) {
      delta = (delta << 7) | (b & 0x7f);
      b = body[i++];
    }
    delta = (delta << 7) | (b & 0x7f);
    tick += delta;
    const status = body[i];
    const len =
      status === 0xff ? 3 + body[i + 2] : (status & 0xf0) === 0xc0 ? 2 : 3;
    out.push({ tick, bytes: body.slice(i, i + len) });
    i += len;
  }
  return out;
}

describe("mid-piece marks (#160)", () => {
  it("collects tempo marks at their ticks", () => {
    const { tempoMarks, meterMarks } = midiNotesFromMusicXml(DRIFT_XML);
    expect(tempoMarks).toEqual([
      { tick: 0, bpm: 120 },
      { tick: 1920, bpm: 60 },
    ]);
    expect(meterMarks).toEqual([
      { tick: 0, meter: "4/4" },
      { tick: 1920, meter: "3/4" },
    ]);
  });

  it("emits a set_tempo per mark in the SMF", () => {
    const events = smfEvents(buildMidiFile(DRIFT_XML));
    const tempos = events.filter(
      (e) => e.bytes[0] === 0xff && e.bytes[1] === 0x51,
    );
    expect(tempos.map((e) => e.tick)).toEqual([0, 1920]);
    const meters = events.filter(
      (e) => e.bytes[0] === 0xff && e.bytes[1] === 0x58,
    );
    expect(meters.map((e) => e.tick)).toEqual([0, 1920]);
  });

  it("does not merge ties across parts", () => {
    const { notes } = midiNotesFromMusicXml(TWOPART_TIE_XML);
    // Part 1's tied D4 (0..960) and part 2's untied D4 (0..960) must
    // both survive — a shared openTies map would drop one.
    expect(notes).toEqual([
      { on: 0, off: 960, midi: 62 },
      { on: 0, off: 960, midi: 62 },
    ]);
  });
});

/**
 * MusicXML → SMF (Standard MIDI File, format 0) builder for the
 * 再生用MIDI export (#99).
 *
 * Pure-JS: parses the concert-pitch MusicXML with DOMParser, walks the
 * note stream honouring <chord/>, <backup>/<forward>, per-measure
 * <divisions>, tie merge (start/stop pairs become one sustained note)
 * and the <sound tempo> / <time> meta events, then serializes a
 * single-track SMF at 480 ticks per quarter.
 *
 * Scope: single-part monophonic output (the engine's contract); chord
 * members and multi-voice <backup> content are still emitted correctly
 * since the walking algorithm is generic.
 */

const TICKS_PER_QUARTER = 480;
/** GM program 60 = French Horn (0-indexed program change byte). */
const HORN_PROGRAM = 60;
const DEFAULT_VELOCITY = 80;

interface MidiNote {
  /** Absolute onset in ticks. */
  on: number;
  /** Absolute release in ticks (> on). */
  off: number;
  midi: number;
}

/** Tempo/meter meta mark at an absolute tick (#160). */
interface TempoMark {
  tick: number;
  bpm: number;
}
interface MeterMark {
  tick: number;
  meter: string;
}

const STEP_TO_SEMITONE: Record<string, number> = {
  C: 0,
  D: 2,
  E: 4,
  F: 5,
  G: 7,
  A: 9,
  B: 11,
};

function noteMidi(el: Element): number | null {
  const pitch = el.querySelector(":scope > pitch");
  if (!pitch) return null;
  const step = pitch.querySelector("step")?.textContent ?? "";
  const base = STEP_TO_SEMITONE[step];
  const octaveText = pitch.querySelector("octave")?.textContent;
  if (base === undefined || octaveText == null) return null;
  const alter = Number(pitch.querySelector("alter")?.textContent ?? 0);
  const octave = Number(octaveText);
  if (!Number.isFinite(alter) || !Number.isFinite(octave)) return null;
  return base + alter + (octave + 1) * 12;
}

function varLen(value: number): number[] {
  let v = Math.max(0, Math.floor(value));
  const out = [v & 0x7f];
  v >>= 7;
  while (v > 0) {
    out.unshift((v & 0x7f) | 0x80);
    v >>= 7;
  }
  return out;
}

function u16(v: number): number[] {
  return [(v >> 8) & 0xff, v & 0xff];
}
function u32(v: number): number[] {
  return [(v >> 24) & 0xff, (v >> 16) & 0xff, (v >> 8) & 0xff, v & 0xff];
}

/** Tempo BPM → microseconds-per-quarter meta event body. */
function tempoMeta(bpm: number): number[] {
  const us = Math.round(60_000_000 / bpm);
  return [0xff, 0x51, 0x03, (us >> 16) & 0xff, (us >> 8) & 0xff, us & 0xff];
}

/** Time-signature meta event body for "n/d" (d must be a power of 2). */
function timeSigMeta(meter: string | null): number[] | null {
  if (!meter) return null;
  const [n, d] = meter.split("/").map(Number);
  if (!Number.isFinite(n) || !Number.isFinite(d) || n <= 0 || d <= 0) {
    return null;
  }
  const dd = Math.round(Math.log2(d));
  if (2 ** dd !== d) return null;
  return [0xff, 0x58, 0x04, n & 0xff, dd & 0xff, 24, 8];
}

/**
 * Parse the concert MusicXML into absolute-tick note events.
 * Throws on malformed XML (same policy as parseScoreDoc).
 */
export function midiNotesFromMusicXml(xml: string): {
  notes: MidiNote[];
  tempoBpm: number;
  meter: string | null;
  tempoMarks: TempoMark[];
  meterMarks: MeterMark[];
} {
  const doc = new DOMParser().parseFromString(xml, "application/xml");
  if (doc.querySelector("parsererror")) {
    throw new Error("MusicXML parse failed");
  }
  const notes: MidiNote[] = [];
  const tempoMarks: TempoMark[] = [];
  const meterMarks: MeterMark[] = [];
  // Per-part walk so <backup> only rewinds its own part's cursor.
  for (const part of Array.from(doc.querySelectorAll("part"))) {
    let divisions = 1; // quarter-note units per <duration> tick
    let cursor = 0;   // divisions
    // pitch -> open tie note, PER PART (#160): a shared map let part 2
    // notes merge into part 1's open ties on the same pitch.
    const openTies = new Map<number, MidiNote>();
    for (const measure of Array.from(part.querySelectorAll(":scope > measure"))) {
      for (const el of Array.from(measure.children)) {
        if (el.tagName === "attributes") {
          const d = el.querySelector("divisions")?.textContent;
          if (d != null && Number.isFinite(Number(d)) && Number(d) > 0) {
            divisions = Number(d);
          }
          // #160: meter changes live inside <attributes><time>.
          const beats = el.querySelector("time > beats")?.textContent?.trim();
          const beatType = el
            .querySelector("time > beat-type")
            ?.textContent?.trim();
          if (beats && beatType) {
            meterMarks.push({
              tick: Math.round((cursor * TICKS_PER_QUARTER) / divisions),
              meter: beats + "/" + beatType,
            });
          }
          continue;
        }
        // #160: tempo marks ride <direction><sound tempo> children (or
        // bare measure-level <sound>) at the cursor position — a
        // tracked-tempo piece emits one mark per changed boundary.
        if (el.tagName === "direction" || el.tagName === "sound") {
          const snd =
            el.tagName === "sound" ? el : el.querySelector("sound[tempo]");
          const t = snd?.getAttribute("tempo");
          const bpm = t != null ? Number(t) : NaN;
          if (Number.isFinite(bpm) && bpm > 0) {
            tempoMarks.push({
              tick: Math.round((cursor * TICKS_PER_QUARTER) / divisions),
              bpm,
            });
          }
          continue;
        }
        if (el.tagName === "backup" || el.tagName === "forward") {
          const dur = Number(el.querySelector("duration")?.textContent ?? 0);
          if (Number.isFinite(dur)) {
            cursor += el.tagName === "backup" ? -dur : dur;
            if (cursor < 0) cursor = 0;
          }
          continue;
        }
        if (el.tagName !== "note") continue;

        const isChord = el.querySelector(":scope > chord") !== null;
        const dur = Number(el.querySelector(":scope > duration")?.textContent ?? 0);
        const isRest = el.querySelector(":scope > rest") !== null;
        const isGrace = el.querySelector(":scope > grace") !== null;
        const midi = isRest || isGrace ? null : noteMidi(el);

        if (midi !== null && dur > 0) {
          const onTick = Math.round((cursor * TICKS_PER_QUARTER) / divisions);
          const offTick = Math.round(
            ((cursor + dur) * TICKS_PER_QUARTER) / divisions,
          );
          const tieStart =
            el.querySelector('tie[type="start"]') !== null;
          const tieStop = el.querySelector('tie[type="stop"]') !== null;
          const open = openTies.get(midi);
          if (tieStop && open && open.on < onTick) {
            // Continuation: extend the open note instead of re-striking.
            open.off = Math.max(open.off, offTick);
            if (!tieStart) openTies.delete(midi);
          } else {
            const note: MidiNote = { on: onTick, off: offTick, midi };
            notes.push(note);
            if (tieStart) openTies.set(midi, note);
          }
        }
        // Chord members share the previous note's onset: the cursor
        // only advances for non-chord notes.
        if (!isChord && Number.isFinite(dur)) cursor += dur;
      }
    }
  }
  notes.sort((a, b) => a.on - b.on || a.midi - b.midi);
  // Multi-part exports repeat the same marks in every part — dedupe.
  const seenT = new Set<string>();
  const tempos = tempoMarks.filter(
    (m) => !seenT.has(m.tick + "@" + m.bpm) && seenT.add(m.tick + "@" + m.bpm),
  );
  const seenM = new Set<string>();
  const meters = meterMarks.filter(
    (m) =>
      !seenM.has(m.tick + "@" + m.meter) && seenM.add(m.tick + "@" + m.meter),
  );
  // A mark after <backup> can collect out of order — sort by tick.
  tempos.sort((a, b) => a.tick - b.tick);
  meters.sort((a, b) => a.tick - b.tick);
  return {
    notes,
    tempoBpm: tempos[0]?.bpm ?? 120,
    meter: meters[0]?.meter ?? null,
    tempoMarks: tempos,
    meterMarks: meters,
  };
}

/** Serialize parsed notes into an SMF format-0 byte array. */
export function buildMidiFile(xml: string): Uint8Array {
  const { notes, tempoBpm, meter, tempoMarks, meterMarks } =
    midiNotesFromMusicXml(xml);

  // Flatten into (tick, order, bytes) events; note-offs sort before
  // note-ons at the same tick so a boundary never overlaps itself.
  interface Ev { tick: number; order: number; bytes: number[] }
  const events: Ev[] = [];
  // #160: every collected mark becomes a meta event at its tick; the
  // head fallbacks keep a markless document playable at 120bpm.
  if (tempoMarks.length === 0) {
    events.push({ tick: 0, order: 0, bytes: tempoMeta(tempoBpm) });
  }
  if (meter != null && meterMarks.length === 0) {
    const m = timeSigMeta(meter);
    if (m) events.push({ tick: 0, order: 0, bytes: m });
  }
  for (const mark of meterMarks) {
    const m = timeSigMeta(mark.meter);
    if (m) events.push({ tick: mark.tick, order: 0, bytes: m });
  }
  for (const mark of tempoMarks) {
    events.push({ tick: mark.tick, order: 0, bytes: tempoMeta(mark.bpm) });
  }
  events.push({ tick: 0, order: 1, bytes: [0xc0, HORN_PROGRAM] });
  for (const n of notes) {
    events.push({
      tick: n.on,
      order: 2,
      bytes: [0x90, n.midi & 0x7f, DEFAULT_VELOCITY],
    });
    events.push({
      tick: n.off,
      order: 1,
      bytes: [0x80, n.midi & 0x7f, 0],
    });
  }
  const lastTick = notes.reduce((m, n) => Math.max(m, n.off), 0);
  events.push({ tick: lastTick, order: 3, bytes: [0xff, 0x2f, 0x00] });
  events.sort((a, b) => a.tick - b.tick || a.order - b.order);

  const track: number[] = [];
  let prev = 0;
  for (const ev of events) {
    track.push(...varLen(ev.tick - prev), ...ev.bytes);
    prev = ev.tick;
  }

  const header = [
    0x4d, 0x54, 0x68, 0x64, // "MThd"
    ...u32(6),
    ...u16(0), // format 0
    ...u16(1), // one track
    ...u16(TICKS_PER_QUARTER),
  ];
  const trackChunk = [
    0x4d, 0x54, 0x72, 0x6b, // "MTrk"
    ...u32(track.length),
    ...track,
  ];
  return new Uint8Array([...header, ...trackChunk]);
}
